INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'History', 'Unit 2', 'Molarum Grade 10 — History Unit 2: Africa and the Colonial Experience (1880s–1960s)', 'Source-grounded Molarum Grade 10 History questions for Unit 2: Africa and the Colonial Experience (1880s–1960s).') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('afc5b43c-7908-465a-81b7-0673fa040336'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'multiple_choice', 'How does the textbook define colonialism?', 'Direct and total dominance of one country by another', 'The textbook defines colonialism as direct and total dominance based on foreign state authority.', 0),('ea18145e-db32-4120-8cb1-69b50b460e19'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'multiple_choice', 'Which idea is inseparably tied to colonialism in the textbook?', 'Imperialism', 'The source says colonialism is inextricably tied to imperialism.', 1),('4aeba274-74ee-481d-8708-4ec9970184f8'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'multiple_choice', 'What was exchanged in legitimate trade after the Atlantic slave trade was abolished?', 'African raw products for European goods', 'Legitimate commerce involved African raw products, especially cash crops, exchanged for European goods.', 2),('d99202c6-3861-4466-8db8-f4bb4d592f95'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'multiple_choice', 'What distinguished many European explorers who arrived in Africa after the 1850s?', 'They were European government agents', 'The textbook describes a considerable number of post-1850 explorers as European government agents.', 3),('d044a5f5-1657-4aab-8532-f41a2dd23790'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'multiple_choice', 'Which economic need was a visible motive for European colonization of Africa?', 'Raw materials and new markets', 'The source identifies demand for raw materials and new market centres as major motives.', 4),('91bad5f0-b69a-4900-8460-fbd8679c2b1c'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'multiple_choice', 'Which resource is listed as an African mining resource sought by Europeans?', 'Diamonds', 'The textbook lists rubber, gold, and diamonds among mining resources sought.', 5),('eac85f29-7788-49da-8d1d-07fb7b651545'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'multiple_choice', 'What strategic interest did European powers seek in Africa?', 'Favourable locations for military and naval bases', 'European powers wanted strategic territories and favourable military and naval base locations.', 6),('b3a14c76-6088-465f-81c7-125650182f23'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'multiple_choice', 'What did the civilizing mission claim Europeans were spreading?', 'Civilization, commerce, and Christianity', 'The source says Europeans presented themselves as spreading civilization, commerce, and Christianity.', 7),('444cfa58-50a1-4b22-8f84-ab60b5a982fa'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'multiple_choice', 'Who led the Berlin Conference according to the textbook?', 'Otto von Bismarck', 'The German Chancellor Otto von Bismarck led the Berlin Conference.', 8),('22457946-c514-4fce-8b5f-438783c663eb'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'multiple_choice', 'Which continent was not invited or involved in the Berlin Conference?', 'Africa', 'The source explicitly states that Africa was not invited or involved.', 9),('229f0862-5353-4f19-8e9d-974961a64f41'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'multiple_choice', 'What did the Berlin Conference confirm as King Leopold II''s private property?', 'The Congo Free State', 'The Conference confirmed the Congo Free State as King Leopold II''s private property.', 10),('3ccb1c8b-531f-4667-8e14-d031f68ed492'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'multiple_choice', 'Which method was one of the colonial administrative systems listed in the textbook?', 'Company rule', 'Company rule is listed alongside direct rule, assimilation, indirect rule, and settler rule.', 11),('59cd9f22-be63-48cb-8fa1-408e4d543d9e'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'multiple_choice', 'What happened to indigenous rulers under direct rule?', 'They were removed and replaced by European personnel', 'The source says indigenous rulers and local governments were removed and replaced by European personnel.', 12),('ecc5656e-f52c-4a41-8c51-7164323d303a'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'multiple_choice', 'Which colonial power made greater use of African customary law under indirect rule?', 'Britain', 'The textbook contrasts British use of African customary law with French policy.', 13),('42271d3c-70e3-4b35-8c85-a48d7c7923d3'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'multiple_choice', 'What happened to fertile African peasant land under settler rule?', 'It was taken and given to minority white settlers', 'The source states that fertile land was taken from African peasants and given to minority white settlers.', 14),('bf8dfb0a-c4e9-4c7a-8fd4-a1775ae8cb61'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'multiple_choice', 'Which was a nonviolent form of African anti-colonial resistance?', 'Use of the indigenous press', 'The source lists the indigenous press, trade unionism, religion, associations, art, and mass migration as nonviolent resistance.', 15),('a627287b-d030-4ebe-822f-893b20d6cb10'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'multiple_choice', 'Which leader resisted French colonial expansion in the Mandinka Empire?', 'Samori Ture', 'Samori Ture led protracted armed resistance to French expansion in the Mandinka Empire.', 16),('db425c53-3799-498d-8bb1-101ae588f55d'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'multiple_choice', 'What policy did Germans use to crush the Maji Maji uprising?', 'Scorched earth', 'The source says Germans destroyed villages under a scorched-earth policy.', 17),('aac99583-ad0d-4461-86df-c2bbe1825948'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'multiple_choice', 'Who led the Herero rebellion against German colonial rule in 1904?', 'Samuel Maharero', 'The source identifies Samuel Maharero as leader of the Herero rebellion in 1904.', 18),('374b0548-8f38-4741-81da-d8f7183f7521'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'multiple_choice', 'What political legacy did artificial colonial boundaries create?', 'Boundary conflicts among many African nations after independence', 'Artificial boundaries became a colonial legacy and caused conflicts after independence.', 19),('acb986c9-364b-4adf-8869-cbb07b1e0a56'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'true_false', 'Colonialism changed Africa-Europe commerce from human merchandise to tropical crops.', 'True', 'The source describes the shift from commerce based on human merchandise to tropical crops.', 20),('e615efff-a653-4098-837e-8e9067540668'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'true_false', 'The principle of effective occupation required a colonial power to establish administration and a police force in a territory.', 'True', 'Article 35 required treaties, a flag, administration, and a police force for effective occupation.', 21),('2a2f9c17-e502-4e66-8ce9-9b8ffd39235b'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'true_false', 'Indirect rule removed every indigenous African ruler from colonial administration.', 'False', 'Indirect rule used indigenous African rulers within colonial administration.', 22),('c7ecb499-8e68-4cd8-8350-308e5632e70a'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'true_false', 'Colonial education encouraged Africans to preserve indigenous technological skills according to the textbook.', 'False', 'The source says colonial education made Africans abandon indigenous technological skills and education.', 23),('ccdd02bf-8976-4f36-8fbe-57b00f90b112'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'fill_blank', 'Name one agricultural raw material listed as sought by Europeans in Africa.', 'Groundnuts, palm oil, wood, cotton, or gum.', 'The source lists these agricultural products as examples of resources sought.', 24),('ce7d44f8-ac06-4394-8822-cc2c09253b40'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'fill_blank', 'Give one condition required by the principle of effective occupation.', 'A treaty with local leaders, flying the colonial flag, or establishing administration with a police force.', 'The textbook lists these requirements under the effective occupation principle.', 25),('94865931-080b-4474-82e2-5e4896f5f00b'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'fill_blank', 'Why did company rule fail according to the textbook?', 'It failed because of shortage of finance and opposition from Africans and missionaries to harsh rule.', 'The source attributes company-rule failure to finance shortages and opposition to its harshness.', 26),('840dc935-56b5-41b9-83f8-2b5da5e8c0e1'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'fill_blank', 'What did French assimilation extend in African colonies?', 'French language, institutions, laws, and customs.', 'The textbook describes assimilation in practice as extending these French institutions and practices.', 27),('1d42ed91-f67d-4677-81d0-398af7b3be6e'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'fill_blank', 'Give one consequence of settler rule for Africans in Kenya.', 'Africans became labourers or landless tenants, and Kikuyu people migrated to urban centres such as Nairobi for employment.', 'The source connects loss of land in the white highlands with labour, tenancy, and migration.', 28),('4c84825c-ea63-46e3-8a3a-01c206afbd0d'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'fill_blank', 'Name one nonviolent form of anti-colonial resistance listed in the textbook.', 'The indigenous press, trade unionism, organised religion, associations, literary or art forms, or mass migrations.', 'The source lists these as nonviolent forms of anti-colonialism.', 29),('7cfd797f-f243-456f-8631-1ce6636047d4'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'fill_blank', 'Why did the Maji Maji uprising begin?', 'It began in response to high taxation, forced labour, forced cotton growing, and forced road building under German rule.', 'The textbook connects the uprising to these German colonial impositions.', 30),('cb1ebc2a-f904-4982-875c-efe1c8a1dd68'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'fill_blank', 'State one economic effect of colonial rule described in the textbook.', 'Africa remained a supplier of raw materials for Europe, natural resources were exploited, or Africans were discouraged from manufacturing.', 'The source identifies these as economic consequences of colonialism.', 31),('e980e7cb-7e63-4a61-8702-a568edb095a8'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'fill_blank', 'In which century did colonialism grow in scope after the Age of Discovery?', '16', 'The source says colonialism grew in scope since the 16th century after the Age of Discovery.', 32),('7c56bc71-e40a-453f-84c9-35e1b2dc3126'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'fill_blank', 'In what year did the Berlin Conference begin?', '1884', 'The Berlin Conference was held from 1884 to 1885.', 33),('5f875cf1-fe82-438e-8245-3e0206821760'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'fill_blank', 'Which article of the Final Act stated the principle of effective occupation?', '35', 'The source identifies Article 35 as the basis for the effective occupation principle.', 34),('8a9d5993-6026-4a24-8017-ec7d9742ee9c'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'fill_blank', 'In what year was the British South Africa Company formed?', '1887', 'The source dates formation of the British South Africa Company to 1887.', 35),('d3d1e665-f713-4652-8139-fdb41f9ab41f'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'fill_blank', 'In what year did the British South Africa Company stop governing its colonies?', '1924', 'The textbook states that the company governed the colonies until 1924.', 36),('bf3be608-6469-4aff-843d-6e9115dd7a3d'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'fill_blank', 'In what year did the Maji Maji uprising begin?', '1905', 'The source dates the Maji Maji challenge to German rule from 1905 to 1907.', 37),('71da114f-22ae-4261-81b2-aada08ed6b40'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'fill_blank', 'In what year did British forces enter Cairo and defeat Urabi Pasha''s revolt?', '1882', 'The textbook states that British forces entered Cairo and defeated the revolt in 1882.', 38),('29e839c0-0dd1-4a01-8210-66b60a6d9558'::uuid, '94e6e18a-dfa8-4893-8b30-eeae37386578'::uuid, 'fill_blank', 'In what year was the Gold Coast colony established over all of Ghana after the Asante resistance was defeated?', '1900', 'The source says Britain established the Gold Coast colony over all of Ghana in 1900 after defeating the resistance.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('9b51b8c2-bc92-4fcd-89bb-d152da13a14f'::uuid, 'afc5b43c-7908-465a-81b7-0673fa040336'::uuid, 'Direct and total dominance of one country by another', TRUE, 0),('a6304d6c-8fd7-4c22-802a-48453afef22b'::uuid, 'afc5b43c-7908-465a-81b7-0673fa040336'::uuid, 'Equal cooperation between independent states', FALSE, 1),('08f811f8-bf6f-4872-8551-590055cbde0c'::uuid, 'afc5b43c-7908-465a-81b7-0673fa040336'::uuid, 'A trade agreement after the slave trade', FALSE, 2),('f6fbae9c-2828-4712-881c-0a4476d44b14'::uuid, 'afc5b43c-7908-465a-81b7-0673fa040336'::uuid, 'A system of indigenous self-government', FALSE, 3),('87c52405-ee79-45c2-82d7-318faedd0fc2'::uuid, 'ea18145e-db32-4120-8cb1-69b50b460e19'::uuid, 'Imperialism', TRUE, 0),('a9c72e70-8b48-460a-8431-21727f8ec9ff'::uuid, 'ea18145e-db32-4120-8cb1-69b50b460e19'::uuid, 'Socialism', FALSE, 1),('069c1091-aea2-48c3-8e77-070bb31ee661'::uuid, 'ea18145e-db32-4120-8cb1-69b50b460e19'::uuid, 'Feudalism', FALSE, 2),('f20df818-5e4b-47f1-8da5-6bf2c62cd3a8'::uuid, 'ea18145e-db32-4120-8cb1-69b50b460e19'::uuid, 'National self-rule', FALSE, 3),('1c7edcd4-e9de-47a9-858f-f7d31d85efa3'::uuid, '4aeba274-74ee-481d-8708-4ec9970184f8'::uuid, 'African raw products for European goods', TRUE, 0),('4fe0a4e7-ee13-4f32-8976-ea362af4dd06'::uuid, '4aeba274-74ee-481d-8708-4ec9970184f8'::uuid, 'Enslaved people for military protection', FALSE, 1),('5948533b-4942-44a8-8e2d-50ce0a967881'::uuid, '4aeba274-74ee-481d-8708-4ec9970184f8'::uuid, 'European land for African manufactured goods', FALSE, 2),('d45586b1-6a66-4664-8dae-df95604c2830'::uuid, '4aeba274-74ee-481d-8708-4ec9970184f8'::uuid, 'Only gold for cotton', FALSE, 3),('c7975330-f6ec-4f43-8855-185adedb6d1a'::uuid, 'd99202c6-3861-4466-8db8-f4bb4d592f95'::uuid, 'They were European government agents', TRUE, 0),('e93754da-5414-4120-8261-4314505e6186'::uuid, 'd99202c6-3861-4466-8db8-f4bb4d592f95'::uuid, 'They were African chiefs', FALS